<script>
document.addEventListener('DOMContentLoaded', function () {
    const toggle = document.getElementById('togglePeriodeMutasiHutang');
    const panel = document.getElementById('periodeMutasiHutang');
    if (!toggle || !panel) return;

    toggle.addEventListener('click', function () {
        const hidden = panel.classList.toggle('d-none');
        toggle.textContent = hidden ? 'Periode mutasi' : 'Sembunyikan periode';
    });
});
</script>
